  .add-card img{filter:invert(1) brightness(2);}

  /* New task form (inline card) */
  .form-card{
    background:#fff; color:#333; border-radius:12px;
    box-shadow:0 10px 20px rgba(0,0,0,0.25);
    overflow:hidden; display:none; margin-bottom:12px;
  }
  .form-body{ padding:16px 14px 8px; }
  .in-title{
    width:100%; box-sizing:border-box; 
    border:1px solid #e3e3e3; border-radius:8px;
    padding:10px 12px; font-size:18px; outline:none;
  }
  .label{ font-weight:700; margin:14px 0 6px; }
  .est-row{ display:flex; gap:8px; align-items:center; }
  .est-num{
    width:64px; height:36px; background:#f3f3f3; border-radius:8px; 
    display:flex; align-items:center; justify-content:center; font-weight:700;
  }
  .est-btn{
    width:36px; height:36px; background:#fff; border:1px solid #e5e5e5;
    border-radius:8px; display:flex; align-items:center; justify-content:center;
  }
  .link-row{ display:flex; gap:16px; color:#777; margin:10px 0 6px; }
  .link-row span{ color:#888; text-decoration:underline; }
  .form-footer{
    display:flex; align-items:center; justify-content:space-between; background:#f4f4f4; 
    padding:10px 12px;
  }
  .save-btn{
    background:#3a3a3a; color:#fff; border:none; border-radius:12px; padding:10px 18px; font-weight:700;
  }
  .cancel{ color:#777; }

  /* Summary footer bar */
  .summary{
    background:rgba(0,0,0,0.12);
    border:1px solid rgba(255,255,255,0.2);
    border-radius:10px;
    padding:12px 14px; color:#fff; display:flex; justify-content:space-between; align-items:center; gap:8px;
  }
  .summary strong{ font-weight:800; }

  /* Toast */
  .toast{
    position:fixed; left:16px; right:16px; bottom:16px;
    background:#fff; color:#333; border-radius:12px; padding:12px; 
    display:none; align-items:center; justify-content:space-between; gap:12px;
    box-shadow:0 8px 22px rgba(0,0,0,0.3);
  }
  .toast .clear-btn{
    background:#2e9e76; color:#fff; border:none; border-radius:8px; padding:10px 16px; font-weight:800;
  }

  /* Confetti */
  .confetti{
    pointer-events:none;
    position:fixed; inset:0; overflow:hidden; display:none;
  }
  .confetti span{
    position:absolute; width:10px; height:10px; border-radius:50%;
    animation:fall 1200ms linear forwards;
    opacity:0.9;
  }
  @keyframes fall{
    from{ transform:translateY(-40px) rotate(0deg); }
    to{ transform:translateY(120vh) rotate(720deg); }
  }

  /* Utility */
  .muted{ opacity:0.85; }
</style>
</head>
<body>
  <div class="app">
    <header class="topbar">
      <div class="brand">
        <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/005.png" alt="check" width="22" height="22">
        <span>Pomofocus</span>
      </div>
      <div class="top-actions">
        <div class="icon-btn btn" title="Stats">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/040.svg" alt="stats" width="18" height="18">
        </div>
        <div class="icon-btn btn" title="Settings">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/033.png" alt="gear" width="18" height="18">
        </div>
        <div class="icon-btn btn" title="Account">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/012.png" alt="user" width="18" height="18">
        </div>
        <div class="icon-btn btn" title="More">
          <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/003.png" alt="menu" width="18" height="18">
